import os
import dash
from dash import Dash, dcc, html
app = Dash(__name__, use_pages=True, pages_folder='pages', title="Jordan's Markets Lab", suppress_callback_exceptions=True)
server = app.server
app.index_string = '\n<!DOCTYPE html>\n<html>\n<head>\n{%metas%}\n<title>{%title%}</title>\n{%favicon%}\n{%css%}\n<style>\nbody {\n    margin: 0;\n    background: #091321;\n    color: #edf3fc;\n    font-family: Arial, sans-serif;\n}\n* { box-sizing: border-box; }\na { color: #45dfc0; text-decoration: none; }\na:hover { text-decoration: underline; }\n.shell { max-width: 1250px; margin: auto; padding: 28px; }\nnav {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 24px;\n    padding: 20px 0;\n    border-bottom: 1px solid #26384f;\n    margin-bottom: 50px;\n}\n.eyebrow {\n    color: #45dfc0;\n    font-size: 12px;\n    letter-spacing: 3px;\n    font-weight: bold;\n}\nh1 { font-size: clamp(32px, 5vw, 56px); margin-bottom: 18px; }\n.intro {\n    color: #a4b4ca;\n    font-size: 18px;\n    line-height: 1.7;\n    max-width: 750px;\n}\n.grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n    gap: 24px;\n    margin: 40px 0;\n}\n.card {\n    background: #142238;\n    padding: 30px;\n    border: 1px solid #26384f;\n    border-radius: 16px;\n}\n.card p { color: #a4b4ca; line-height: 1.7; }\n.tag { color: #45dfc0; font-size: 12px; letter-spacing: 2px; }\n.button {\n    display: inline-block;\n    background: #45dfc0;\n    color: #091321;\n    padding: 13px 18px;\n    border-radius: 8px;\n    font-weight: bold;\n    margin-top: 15px;\n}\nfooter {\n    color: #a4b4ca;\n    font-size: 13px;\n    border-top: 1px solid #26384f;\n    padding: 25px 0;\n    margin-top: 50px;\n}\n</style>\n</head>\n<body>\n{%app_entry%}\n<footer style="border:0;padding:0;margin:0">\n{%config%}{%scripts%}{%renderer%}\n</footer>\n</body>\n</html>\n'

def project_card(number, title, description, path):
    return html.Div([html.Div(number, className='tag'), html.H2(title), html.P(description), dcc.Link('Explore project →', href=path, className='button')], className='card')
home_layout = html.Div([html.Div('JORDAN ADEGBITE / MARKETS & ANALYTICS', className='eyebrow'), html.H1("Jordan's Markets Lab"), html.P('Exploring financial markets through interactive Python projects. Adjust assumptions, compare scenarios and investigate how returns, pricing and risk change.', className='intro'), html.Div([project_card('PROJECT 01 / PORTFOLIO ANALYSIS', 'Portfolio Risk', 'Explore portfolio allocations, historical returns, correlations, volatility and Value-at-Risk.', '/portfolio'), project_card('PROJECT 02 / DERIVATIVES', 'Options & Greeks', 'Calculate Black–Scholes call and put prices and explore Delta, Gamma, Vega, Theta and Rho.', '/options'), project_card('PROJECT 03 / MARKET MONITORING', 'Market Screener', 'Filter and sort a curated stock universe and explore sector performance through an interactive heatmap.', '/screener'), project_card('PROJECT 04 / TRADE OPERATIONS', 'Trade Blotter & Risk Report', 'Review daily bookings, analyse mark P&L by strategy and sector, flag potential duplicates and download an HTML risk report.', '/blotter')], className='grid'), html.P('A growing collection of guided projects, built with Python, Dash and Plotly.', className='intro')])

def connection_page(title):
    return html.Div([html.Div('PROJECT INTEGRATION', className='eyebrow'), html.H1(title), html.P('Navigation is ready. The working tool will be connected in the next build steps.', className='intro'), dcc.Link('← Back to projects', href='/')], className='card')
dash.register_page('home', path='/', name='Home', layout=home_layout)
app.layout = html.Div([html.Nav([dcc.Link('Markets Lab', href='/'), dcc.Link('Portfolio Risk', href='/portfolio'), dcc.Link('Options & Greeks', href='/options'), dcc.Link('Market Screener', href='/screener'), dcc.Link('Trade Blotter', href='/blotter')]), dash.page_container, html.Footer('Jordan Adegbite · Educational models and historical analysis · Assumptions and limitations accompany each tool.')], className='shell')
if __name__ == '__main__':
    app.run(debug=False, port=int(os.environ.get('PORT', 8052)))
